<script setup lang="ts">
import { nextTick, onMounted, onUnmounted, ref } from 'vue'
import { stickerUrl, isVideoSticker } from '../../utils/stickers'
const props = defineProps<{ pack: { title: string; items: string[] }; added: boolean; official: boolean }>()
const emit = defineEmits<{ (e: 'close'): void; (e: 'toggle'): void; (e: 'select', item: string): void }>()
const modal = ref<HTMLElement | null>(null)
let priorFocus: HTMLElement | null = null
onMounted(() => { priorFocus = document.activeElement as HTMLElement; nextTick(() => modal.value?.focus()) })
onUnmounted(() => priorFocus?.focus())
function keys(e: KeyboardEvent) { if (e.key === 'Escape') { e.stopPropagation(); emit('close'); return }; if (e.key !== 'Tab' || !modal.value) return; const els = Array.from(modal.value.querySelectorAll<HTMLElement>('button:not(:disabled)')); if (!els.length) return; if (e.shiftKey && (document.activeElement === els[0] || document.activeElement === modal.value)) { e.preventDefault(); els[els.length-1].focus() } else if (!e.shiftKey && document.activeElement === els[els.length-1]) { e.preventDefault(); els[0].focus() } }
</script>
<template><Teleport to="body"><div class="preview-overlay" @click.self="emit('close')" @keydown="keys"><section ref="modal" class="preview-dialog" role="dialog" aria-modal="true" aria-labelledby="pack-preview-title" tabindex="-1"><header><div><h2 id="pack-preview-title">{{ props.pack.title }}</h2><p>{{ props.pack.items.length }} стикеров</p></div><button type="button" class="preview-close" aria-label="Закрыть" @click="emit('close')">×</button></header><div class="preview-grid"><button v-for="item in props.pack.items" :key="item" type="button" class="preview-sticker" aria-label="Отправить стикер" @click="emit('select', item)"><video v-if="isVideoSticker(item)" :src="stickerUrl(item)" autoplay muted loop playsinline /><img v-else :src="stickerUrl(item)" alt="Стикер" /></button></div><button v-if="props.official" type="button" class="preview-action" @click="emit('toggle')">{{ props.added ? 'Убрать из панели' : 'Добавить набор' }}</button><p v-else class="preview-note">Ваш набор стикеров</p></section></div></Teleport></template>
<style scoped>
.preview-overlay { position:fixed; inset:0; z-index:12000; display:flex; align-items:center; justify-content:center; padding:var(--space-4); }.preview-dialog { width:min(100%,420px); max-height:calc(100dvh - 32px); overflow:auto; padding:var(--space-6); border-radius:24px; color:var(--text); background:var(--card); box-shadow:0 24px 70px rgba(0,0,0,.4); }.preview-dialog header { display:flex; align-items:flex-start; justify-content:space-between; gap:var(--space-3); }.preview-dialog h2 { margin:0; font-size:var(--text-20); }.preview-dialog header p,.preview-note { color:var(--muted); font-size:var(--text-14); margin:var(--space-1) 0 0; }.preview-close { width:40px; height:40px; border-radius:50%; background:var(--surface); color:var(--text); font-size:24px; cursor:pointer; }.preview-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:var(--space-2); margin:var(--space-5) 0; }.preview-sticker { aspect-ratio:1; min-width:0; padding:var(--space-1); border-radius:var(--radius-md); background:transparent; cursor:pointer; }.preview-sticker:hover { background:var(--surface); }.preview-sticker img,.preview-sticker video { width:100%; height:100%; object-fit:contain; }.preview-action { width:100%; min-height:48px; border-radius:var(--radius-md); background:var(--surface); color:var(--text); font:inherit; font-weight:600; cursor:pointer; }
</style>
